@@ -0,0 +1,162 @@
+import { zodResolver } from "@hookform/resolvers/zod";
+import { useForm } from "react-hook-form";
+import { z } from "zod";
+import { Button } from "@/components/ui/button";
+import { Input } from "@/components/ui/input";
+import { Label } from "@/components/ui/label";
+import { Textarea } from "@/components/ui/textarea";
+import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
+import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
+import { ClientType } from "@/types/crm";
+import { type Severity, type Status, type ComplaintType, type ReferenceType } from "@/types/crm";
+
+const clientFeedbackSchema = z.object({
+  feedback_id: z.string().min(1, "Feedback ID is required"),
+  date: z.string().min(1, "Date is required"),
+  client_id: z.string().min(1, "Client ID is required"),
+  reference_type: z.string().min(1, "Reference type is required"),
+  reference_id: z.string().optional(),
+  overall_rating: z.number().min(1).max(5),
+  quality_rating: z.number().min(1).max(5),
+  timeliness_rating: z.number().min(1).max(5),
+  communication_rating: z.number().min(1).max(5),
+  would_recommend: z.boolean(),
+  comments: z.string().optional(),
+});
+
+const clientComplaintSchema = z.object({
+  complaint_id: z.string().min(1, "Complaint ID is required"),
+  date_raised: z.string().min(1, "Date raised is required"),
+  client_id: z.string().min(1, "Client ID is required"),
+  reference_type: z.string().min(1, "Reference type is required"),
+  reference_id: z.string().optional(),
+  complaint_type: z.string().min(1, "Complaint type is required"),
+  severity: z.string().min(1, "Severity is required"),
+  description: z.string().optional(),
+  root_cause: z.string().optional(),
+  status: z.string().min(1, "Status is required"),
+  owner_id: z.string().optional(),
+  closure_date: z.string().optional(),
+  notes: z.string().optional(),
+});
+
+type ClientFeedbackFormData = z.infer<typeof clientFeedbackSchema>;
+type ClientComplaintFormData = z.infer<typeof clientComplaintSchema>;
+
+interface ClientFeedbackFormProps {
+  clientType: ClientType;
+  initialData?: Partial<ClientFeedbackFormData | ClientComplaintFormData>;
+  onSubmit: (data: ClientFeedbackFormData | ClientComplaintFormData) => Promise<void>;
+  onCancel?: () => void;
+  isLoading?: boolean;
+}
+
+export function ClientFeedbackForm({ clientType, initialData, onSubmit, onCancel, isLoading }: ClientFeedbackFormProps) {
+  const getSchema = () => {
+    switch (clientType) {
+      case "client-feedback": return clientFeedbackSchema;
+      case "client-complaint": return clientComplaintSchema;
+      default: return clientFeedbackSchema;
+    }
+  };
+
+  const form = useForm<ClientFeedbackFormData | ClientComplaintFormData>({
+    resolver: zodResolver(getSchema()),
+    defaultValues: initialData,
+  });
+
+  const handleSubmit = async (data: ClientFeedbackFormData | ClientComplaintFormData) => {
+    await onSubmit(data);
+  };
+
+  const getFields = () => {
+    switch (clientType) {
+      case "client-feedback":
+        return [
+          { name: "feedback_id", label: "Feedback ID", type: "text" },
+          { name: "date", label: "Date", type: "date" },
+          { name: "client_id", label: "Client ID", type: "text" },
+          { name: "reference_type", label: "Reference Type", type: "text" },
+          { name: "reference_id", label: "Reference ID", type: "text" },
+          { name: "overall_rating", label: "Overall Rating", type: "number" },
+          { name: "quality_rating", label: "Quality Rating", type: "number" },
+          { name: "timeliness_rating", label: "Timeliness Rating", type: "number" },
+          { name: "communication_rating", label: "Communication Rating", type: "number" },
+          { name: "would_recommend", label: "Would Recommend", type: "boolean" },
+        ];
+      case "client-complaint":
+        return [
+          { name: "complaint_id", label: "Complaint ID", type: "text" },
+          { name: "date_raised", label: "Date Raised", type: "date" },
+          { name: "client_id", label: "Client ID", type: "text" },
+          { name: "reference_type", label: "Reference Type", type: "text" },
+          { name: "reference_id", label: "Reference ID", type: "text" },
+          { name: "complaint_type", label: "Complaint Type", type: "text" },
+          { name: "severity", label: "Severity", type: "text" },
+          { name: "status", label: "Status", type: "text" },
+        ];
+      default:
+        return [];
+    }
+  };
+
+  return (
+    <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-6">
+      <Card>
+        <CardHeader>
+          <CardTitle>Create {clientType.charAt(0).toUpperCase() + clientType.slice(1, clientType.indexOf(\"-\")).toUpperCase() + clientType.slice(clientType.indexOf(\"-\") + 1)}</CardTitle>
+        </CardHeader>
+        <CardContent className="space-y-4">
+          {getFields().map((field) => (
+            <div key={field.name} className="space-y-2">
+              <Label htmlFor={field.name}>{field.label}</Label>
+              {field.type === "boolean" ? (
+                <Select
+                  onValueChange={(value) => form.setValue(field.name as any, value === "true")}
+                  defaultValue={form.getValues(field.name as any) ? "true" : "false"}
+                >
+                  <SelectTrigger>
+                    <SelectValue />
+                  </SelectTrigger>
+                  <SelectContent>
+                    <SelectItem value="true">Yes</SelectItem>
+                    <SelectItem value="false">No</SelectItem>
+                  </SelectContent>
+                </Select>
+              ) : (
+                <Input
+                  id={field.name}
+                  type={field.type}
+                  {...form.register(field.name as never)}
+                />
+              )}
+              {form.formState.errors[field.name as keyof typeof form.formState.errors] && (
+                <p className="text-sm text-red-500">
+                  {(form.formState.errors[field.name as keyof typeof form.formState.errors] as { message: string }).message}
+                </p>
+              )}
+            </div>
+          ))}
+
+          {(clientType === "client-feedback" ? ("comments" in initialData || true) : ("description" in initialData || true)) && (
+            <div className="space-y-2">
+              <Label htmlFor="comments">{clientType === "client-feedback" ? "Comments" : "Description"}</Label>
+              <Textarea id="comments" {...form.register("comments" as never)} />
+            </div>
+          )}
+        </CardContent>
+      </Card>
+
+      <div className="flex gap-3 justify-end">
+        {onCancel && (
+          <Button type="button" variant="outline" onClick={onCancel}>
+            Cancel
+          </Button>
+        )}
+        <Button type="submit" disabled={isLoading}>
+          {isLoading ? "Saving..." : "Save"}
+        </Button>
+      </div>
+    </form>
+  );
+}

