type InstagramFormData = z.infer<typeof instagramMetricSchema>;
type LinkedInFormData = z.infer<typeof linkedinMetricSchema>;
type WebsiteFormData = z.infer<typeof websiteMetricSchema>;

interface MetricFormProps {
  metricType: MetricType;
  initialData?: Partial<InstagramFormData | LinkedInFormData | WebsiteFormData>;
  onSubmit: (data: InstagramFormData | LinkedInFormData | WebsiteFormData) => Promise<void>;
  onCancel?: () => void;
  isLoading?: boolean;
}

export function MetricForm({ metricType, initialData, onSubmit, onCancel, isLoading }: MetricFormProps) {
  const getSchema = () => {
    switch (metricType) {
      case "instagram": return instagramMetricSchema;
      case "linkedin": return linkedinMetricSchema;
      case "website": return websiteMetricSchema;
      default: return instagramMetricSchema;
    }
  };

  const form = useForm<InstagramFormData | LinkedInFormData | WebsiteFormData>({
    resolver: zodResolver(getSchema()),
    defaultValues: initialData,
  });

  const handleSubmit = async (data: InstagramFormData | LinkedInFormData | WebsiteFormData) => {
    await onSubmit(data);
  };

  const getFields = () => {
    switch (metricType) {
      case "instagram":
        return [
          { name: "metric_id", label: "Metric ID", type: "text" },
          { name: "period_yyyymm", label: "Period (YYYYMM)", type: "text" },
          { name: "followers_start", label: "Followers Start", type: "number" },
          { name: "followers_end", label: "Followers End", type: "number" },
          { name: "followers_net_add", label: "Net Add", type: "number" },
          { name: "impressions", label: "Impressions", type: "number" },
          { name: "reach", label: "Reach", type: "number" },
          { name: "profile_visits", label: "Profile Visits", type: "number" },
          { name: "likes", label: "Likes", type: "number" },
          { name: "comments", label: "Comments", type: "number" },
          { name: "shares", label: "Shares", type: "number" },
          { name: "saves", label: "Saves", type: "number" },
          { name: "engagement_rate", label: "Engagement Rate", type: "number" },
        ];
      case "linkedin":
        return [
          { name: "metric_id", label: "Metric ID", type: "text" },
          { name: "period_yyyymm", label: "Period (YYYYMM)", type: "text" },
          { name: "followers_start", label: "Followers Start", type: "number" },
          { name: "followers_end", label: "Followers End", type: "number" },
          { name: "followers_net_add", label: "Net Add", type: "number" },
          { name: "impressions", label: "Impressions", type: "number" },
          { name: "reach", label: "Reach", type: "number" },
          { name: "profile_views", label: "Profile Views", type: "number" },
          { name: "reactions", label: "Reactions", type: "number" },
          { name: "comments", label: "Comments", type: "number" },
        ];
      case "website":
        return [
          { name: "metric_id", label: "Metric ID", type: "text" },
          { name: "period_yyyymm", label: "Period (YYYYMM)", type: "text" },
          { name: "sessions", label: "Sessions", type: "number" },
          { name: "users", label: "Users", type: "number" },
          { name: "page_views", label: "Page Views", type: "number" },
          { name: "bounce_rate", label: "Bounce Rate", type: "number" },
          { name: "contact_form_submissions", label: "Contact Forms", type: "number" },
          { name: "consultation_requests", label: "Consultations", type: "number" },
          { name: "leads_count", label: "Leads", type: "number" },
          { name: "inquiry_count", label: "Inquiries", type: "number" },
        ];
      default:
        return [];
    }
  };

  return (
    <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Create {metricType.charAt(0).toUpperCase() + metricType.slice(1)} Metric</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {getFields().map((field) => (
            <div key={field.name} className="space-y-2">
              <Label htmlFor={field.name}>{field.label}</Label>
              <Input
                id={field.name}
                type={field.type}
                {...form.register(field.name as never, { valueAsNumber: field.type === "number" })}
              />
              {form.formState.errors[field.name as keyof typeof form.formState.errors] && (
                <p className="text-sm text-red-500">
                  {(form.formState.errors[field.name as keyof typeof form.formState.errors] as { message: string }).message}
                </p>
              )}
            </div>
          ))}

          <div className="space-y-2">
            <Label htmlFor="notes">Notes</Label>
            <Textarea id="notes" {...form.register("notes")} />
          </div>
        </CardContent>
      </Card>

      <div className="flex gap-3 justify-end">
        {onCancel && (
          <Button type="button" variant="outline" onClick={onCancel}>
            Cancel
          </Button>
        )}
        <Button type="submit" disabled={isLoading}>
          {isLoading ? "Saving..." : "Save"}
        </Button>
      </div>
    </form>
  );
