from __future__ import annotations

import uuid

from fastapi import APIRouter, Depends, HTTPException, Query, status
from sqlalchemy.orm import Session

from src.backend.core.deps import get_current_user
from src.backend.db.session import get_db
from src.backend.models.user import User
from src.backend.schemas.research_collaboration import (
    ResearchCollaborationCreate,
    ResearchCollaborationListResponse,
    ResearchCollaborationRead,
    ResearchCollaborationUpdate,
)
from src.backend.services import research_collaboration_service

router = APIRouter(prefix="/api/research-collaborations", tags=["research-collaborations"])


@router.get("", response_model=ResearchCollaborationListResponse)
def list_research_collaborations(
    _: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
    page: int = Query(default=1, ge=1),
    page_size: int = Query(default=20, ge=1, le=100),
) -> ResearchCollaborationListResponse:
    items, total = research_collaboration_service.list_research_collaborations_service(
        db, page=page, page_size=page_size
    )
    return ResearchCollaborationListResponse(
        items=[ResearchCollaborationRead.model_validate(i) for i in items],
        total=total,
        page=page,
        page_size=page_size,
    )


@router.post("", response_model=ResearchCollaborationRead, status_code=status.HTTP_201_CREATED)
def create_research_collaboration(
    body: ResearchCollaborationCreate,
    current_user: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> ResearchCollaborationRead:
    collab = research_collaboration_service.create_research_collaboration_service(
        db, body, current_user.id
    )
    return ResearchCollaborationRead.model_validate(collab)


@router.get("/{collab_id}", response_model=ResearchCollaborationRead)
def get_research_collaboration(
    collab_id: uuid.UUID,
    _: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> ResearchCollaborationRead:
    collab = research_collaboration_service.get_research_collaboration_service(db, collab_id)
    if not collab:
        raise HTTPException(status_code=404, detail="Research collaboration not found")
    return ResearchCollaborationRead.model_validate(collab)


@router.patch("/{collab_id}", response_model=ResearchCollaborationRead)
def update_research_collaboration(
    collab_id: uuid.UUID,
    body: ResearchCollaborationUpdate,
    current_user: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
) -> ResearchCollaborationRead:
    collab = research_collaboration_service.update_research_collaboration_service(
        db, collab_id, body, current_user.id
    )
    if not collab:
        raise HTTPException(status_code=404, detail="Research collaboration not found")
    return ResearchCollaborationRead.model_validate(collab)


@router.delete("/{collab_id}", status_code=status.HTTP_204_NO_CONTENT, response_class=None)
def delete_research_collaboration(
    collab_id: uuid.UUID,
    current_user: User = Depends(get_current_user),  # noqa: B008
    db: Session = Depends(get_db),  # noqa: B008
):
    ok = research_collaboration_service.delete_research_collaboration_service(
        db, collab_id, current_user.id
    )
    if not ok:
        raise HTTPException(status_code=404, detail="Research collaboration not found")
    return None

