import {
  ResearchCollaboration,
  ResearchCollaborationListResponse,
  ResearchCollaborationCreate,
  ResearchInnovation,
  ResearchInnovationListResponse,
  ResearchInnovationCreate,
} from "@/types/rnd";

export type { ResearchCollaboration, ResearchInnovation, ResearchCollaborationCreate, ResearchInnovationCreate };

const API_BASE_URL = "/api";

class RndApiError extends Error {
  constructor(public status: number, public body: unknown) {
    super(`R&D API Error: ${status}`);
    this.name = "RndApiError";
  }
}

async function rndRequest<T>(
  path: string,
  options: RequestInit = {}
): Promise<T> {
  const token = localStorage.getItem("access_token");
  const headers: Record<string, string> = {
    ...(options.headers as Record<string, string>),
  };
  if (token) {
    headers["Authorization"] = `Bearer ${token}`;
  }

  if (!headers["Content-Type"] && !(options.body instanceof FormData)) {
    headers["Content-Type"] = "application/json";
  }

  let response = await fetch(path, { ...options, headers });

  if (response.status === 401) {
    const refresh = localStorage.getItem("refresh_token");
    if (refresh) {
      try {
        const refreshResponse = await fetch(`${API_BASE_URL}/auth/refresh`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ refresh_token: refresh }),
        });
        if (refreshResponse.ok) {
          const tokens = await refreshResponse.json();
          localStorage.setItem("access_token", tokens.access_token);
          headers["Authorization"] = `Bearer ${tokens.access_token}`;
          response = await fetch(path, { ...options, headers });
        } else {
          localStorage.removeItem("access_token");
          localStorage.removeItem("refresh_token");
          window.location.href = "/login";
          throw new RndApiError(401, null);
        }
      } catch {
        localStorage.removeItem("access_token");
        localStorage.removeItem("refresh_token");
        window.location.href = "/login";
        throw new RndApiError(401, null);
      }
    }
  }

  if (!response.ok) {
    const body = await response.json().catch(() => null);
    throw new RndApiError(response.status, body);
  }

  return response.json();
}

export const rndApi = {
  listCollaborations: async (
    params?: { page?: number; page_size?: number; q?: string }
  ): Promise<ResearchCollaborationListResponse> => {
    const searchParams = new URLSearchParams();
    if (params?.page) searchParams.set("page", String(params.page));
    if (params?.page_size) searchParams.set("page_size", String(params.page_size));
    if (params?.q) searchParams.set("q", params.q);
    const query = searchParams.toString();
    const endpoint = `/api/research-collaborations${query ? `?${query}` : ""}`;
    return rndRequest<ResearchCollaborationListResponse>(endpoint, { method: "GET" });
  },

  getCollaboration: async (id: string): Promise<ResearchCollaboration> => {
    const endpoint = `/api/research-collaborations/${id}`;
    return rndRequest<ResearchCollaboration>(endpoint);
  },

  createCollaboration: async (data: ResearchCollaborationCreate): Promise<ResearchCollaboration> => {
    const endpoint = `/api/research-collaborations`;
    return rndRequest<ResearchCollaboration>(endpoint, {
      method: "POST",
      body: JSON.stringify(data),
    });
  },

  updateCollaboration: async (id: string, data: Partial<ResearchCollaborationCreate>): Promise<ResearchCollaboration> => {
    const endpoint = `/api/research-collaborations/${id}`;
    return rndRequest<ResearchCollaboration>(endpoint, {
      method: "PATCH",
      body: JSON.stringify(data),
    });
  },

  deleteCollaboration: async (id: string): Promise<void> => {
    const endpoint = `/api/research-collaborations/${id}`;
    await rndRequest<void>(endpoint, { method: "DELETE" });
  },

  listInnovations: async (
    params?: { page?: number; page_size?: number; q?: string }
  ): Promise<ResearchInnovationListResponse> => {
    const searchParams = new URLSearchParams();
    if (params?.page) searchParams.set("page", String(params.page));
    if (params?.page_size) searchParams.set("page_size", String(params.page_size));
    if (params?.q) searchParams.set("q", params.q);
    const query = searchParams.toString();
    const endpoint = `/api/research-innovations${query ? `?${query}` : ""}`;
    return rndRequest<ResearchInnovationListResponse>(endpoint, { method: "GET" });
  },

  getInnovation: async (id: string): Promise<ResearchInnovation> => {
    const endpoint = `/api/research-innovations/${id}`;
    return rndRequest<ResearchInnovation>(endpoint);
  },

  createInnovation: async (data: ResearchInnovationCreate): Promise<ResearchInnovation> => {
    const endpoint = `/api/research-innovations`;
    return rndRequest<ResearchInnovation>(endpoint, {
      method: "POST",
      body: JSON.stringify(data),
    });
  },

  updateInnovation: async (id: string, data: Partial<ResearchInnovationCreate>): Promise<ResearchInnovation> => {
    const endpoint = `/api/research-innovations/${id}`;
    return rndRequest<ResearchInnovation>(endpoint, {
      method: "PATCH",
      body: JSON.stringify(data),
    });
  },

  deleteInnovation: async (id: string): Promise<void> => {
    const endpoint = `/api/research-innovations/${id}`;
    await rndRequest<void>(endpoint, { method: "DELETE" });
  },
};

