  linked_innovation_id: z.string().optional(),
  linked_project_id: z.string().optional(),
  primary_internal_owner_id: z.string().optional(),
  secondary_internal_owner_id: z.string().optional(),
  expected_output: z.string().min(1, "Expected output is required"),
  actual_output: z.string().optional(),
  notes: z.string().optional(),
});

type CollaborationFormData = z.infer<typeof collaborationSchema>;

interface CollaborationFormProps {
  initialData?: Partial<CollaborationFormData>;
  onSubmit: (data: CollaborationFormData) => Promise<void>;
  onCancel?: () => void;
  isLoading?: boolean;
}

export function CollaborationForm({ initialData, onSubmit, onCancel, isLoading }: CollaborationFormProps) {
  const form = useForm<CollaborationFormData>({
    resolver: zodResolver(collaborationSchema),
    defaultValues: initialData,
  });

  const fields = [
    { name: "collab_id", label: "Collab ID", type: "text" },
    { name: "institution_name", label: "Institution Name", type: "text" },
    { name: "institution_type", label: "Institution Type", type: "text" },
    { name: "department_or_lab", label: "Department / Lab", type: "text" },
    { name: "faculty_or_pi_name", label: "Faculty / PI Name", type: "text" },
    { name: "collab_type", label: "Collab Type", type: "text" },
    { name: "domain", label: "Domain", type: "text" },
    { name: "start_date", label: "Start Date", type: "date" },
    { name: "end_date", label: "End Date", type: "date" },
    { name: "collab_status", label: "Status", type: "text" },
    { name: "engagement_model", label: "Engagement Model", type: "text" },
    { name: "linked_innovation_id", label: "Linked Innovation ID", type: "text" },
    { name: "linked_project_id", label: "Linked Project ID", type: "text" },
    { name: "expected_output", label: "Expected Output", type: "text" },
    { name: "actual_output", label: "Actual Output", type: "text" },
  ];

  return (
    <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Create Research Collaboration</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {fields.map((field) => (
            <div key={field.name} className="space-y-2">
              <Label htmlFor={field.name}>{field.label}</Label>
              <Input
                id={field.name}
                type={field.type}
                {...form.register(field.name as never)}
              />
              {form.formState.errors[field.name as keyof typeof form.formState.errors] && (
                <p className="text-sm text-red-500">
                  {(form.formState.errors[field.name as keyof typeof form.formState.errors] as { message: string }).message}
                </p>
              )}
            </div>
          ))}

          <div className="space-y-2">
            <Label htmlFor="notes">Notes</Label>
            <Textarea id="notes" {...form.register("notes")} />
          </div>
        </CardContent>
      </Card>

      <div className="flex gap-3 justify-end">
        {onCancel && (
          <Button type="button" variant="outline" onClick={onCancel}>
            Cancel
          </Button>
        )}
        <Button type="submit" disabled={isLoading}>
          {isLoading ? "Saving..." : "Save"}
        </Button>
      </div>
    </form>
  );
}

