import { ClientFeedbackListResponse, ClientComplaintListResponse, ClientFeedback, ClientComplaint, ClientFeedbackCreate, ClientComplaintCreate } from "@/types/crm";

export type { ClientFeedback, ClientComplaint, ClientFeedbackCreate, ClientComplaintCreate };

const API_BASE_URL = "/api";

class CRMApiError extends Error {
  constructor(public status: number, public body: unknown) {
    super(`CRM API Error: ${status}`);
    this.name = "CRMApiError";
  }
}

async function crmRequest<T>(
  path: string,
  options: RequestInit = {}
): Promise<T> {
  const token = localStorage.getItem("access_token");
  const headers: Record<string, string> = {
    ...(options.headers as Record<string, string>),
  };
  if (token) {
    headers["Authorization"] = `Bearer ${token}`;
  }

  if (!headers["Content-Type"] && !(options.body instanceof FormData)) {
    headers["Content-Type"] = "application/json";
  }

  let response = await fetch(path, { ...options, headers });

  if (response.status === 401) {
    const refresh = localStorage.getItem("refresh_token");
    if (refresh) {
      try {
        const refreshResponse = await fetch(`${API_BASE_URL}/auth/refresh`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ refresh_token: refresh }),
        });
        if (refreshResponse.ok) {
          const tokens = await refreshResponse.json();
          localStorage.setItem("access_token", tokens.access_token);
          headers["Authorization"] = `Bearer ${tokens.access_token}`;
          response = await fetch(path, { ...options, headers });
        } else {
          localStorage.removeItem("access_token");
          localStorage.removeItem("refresh_token");
          window.location.href = "/login";
          throw new CRMApiError(401, null);
        }
      } catch {
        localStorage.removeItem("access_token");
        localStorage.removeItem("refresh_token");
        window.location.href = "/login";
        throw new CRMApiError(401, null);
      }
    }
  }

  if (!response.ok) {
    const body = await response.json().catch(() => null);
    throw new CRMApiError(response.status, body);
  }

  return response.json();
}

export const crmApi = {
  listClientFeedbacks: async (
    clientType: "client-feedback" | "client-complaint",
    params?: { page?: number; page_size?: number; q?: string }
  ): Promise<ClientFeedbackListResponse | ClientComplaintListResponse> => {
    const searchParams = new URLSearchParams();
    if (params?.page) searchParams.set("page", String(params.page));
    if (params?.page_size) searchParams.set("page_size", String(params.page_size));
    if (params?.q) searchParams.set("q", params.q);
    const query = searchParams.toString();
    const endpoint = `/api/${clientType}${query ? `?${query}` : ""}`;
    const response = await crmRequest<ClientFeedbackListResponse | ClientComplaintListResponse>(endpoint, {
      method: "GET",
    });
    return response;
  },

  createClientFeedback: async (
    clientType: "client-feedback" | "client-complaint",
    data: Record<string, unknown>
  ): Promise<ClientFeedback | ClientComplaint> => {
    const endpoint = `/api/${clientType}`;
    const response = await crmRequest<ClientFeedback | ClientComplaint>(endpoint, {
      method: "POST",
      body: JSON.stringify(data),
    });
    return response;
  },

  getClientFeedback: async (clientType: "client-feedback" | "client-complaint", id: string): Promise<ClientFeedback | ClientComplaint> => {
    const endpoint = `/api/${clientType}/${id}`;
    const response = await crmRequest<ClientFeedback | ClientComplaint>(endpoint);
    return response;
  },

  updateClientFeedback: async (
    clientType: "client-feedback" | "client-complaint",
    id: string,
    data: Record<string, unknown>
  ): Promise<ClientFeedback | ClientComplaint> => {
    const endpoint = `/api/${clientType}/${id}`;
    const response = await crmRequest<ClientFeedback | ClientComplaint>(endpoint, {
      method: "PATCH",
      body: JSON.stringify(data),
    });
    return response;
  },

  deleteClientFeedback: async (clientType: "client-feedback" | "client-complaint", id: string): Promise<void> => {
    const endpoint = `/api/${clientType}/${id}`;
    await crmRequest<void>(endpoint, {
      method: "DELETE",
    });
  },
};

