          { name: "would_recommend", label: "Would Recommend", type: "boolean" },
        ];
      case "client-complaint":
        return [
          { name: "complaint_id", label: "Complaint ID", type: "text" },
          { name: "date_raised", label: "Date Raised", type: "date" },
          { name: "client_id", label: "Client ID", type: "text" },
          { name: "reference_type", label: "Reference Type", type: "text" },
          { name: "reference_id", label: "Reference ID", type: "text" },
          { name: "complaint_type", label: "Complaint Type", type: "text" },
          { name: "severity", label: "Severity", type: "text" },
          { name: "status", label: "Status", type: "text" },
        ];
      default:
        return [];
    }
  };

  return (
    <form onSubmit={form.handleSubmit(handleSubmit)} className="space-y-6">
      <Card>
        <CardHeader>
          <CardTitle>Create {clientType.charAt(0).toUpperCase() + clientType.slice(1, clientType.indexOf(\"-\")).toUpperCase() + clientType.slice(clientType.indexOf(\"-\") + 1)}</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          {getFields().map((field) => (
            <div key={field.name} className="space-y-2">
              <Label htmlFor={field.name}>{field.label}</Label>
              {field.type === "boolean" ? (
                <Select
                  onValueChange={(value) => form.setValue(field.name as any, value === "true")}
                  defaultValue={form.getValues(field.name as any) ? "true" : "false"}
                >
                  <SelectTrigger>
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="true">Yes</SelectItem>
                    <SelectItem value="false">No</SelectItem>
                  </SelectContent>
                </Select>
              ) : (
                <Input
                  id={field.name}
                  type={field.type}
                  {...form.register(field.name as never)}
                />
              )}
              {form.formState.errors[field.name as keyof typeof form.formState.errors] && (
                <p className="text-sm text-red-500">
                  {(form.formState.errors[field.name as keyof typeof form.formState.errors] as { message: string }).message}
                </p>
              )}
            </div>
          ))}

          {(clientType === "client-feedback" ? ("comments" in initialData || true) : ("description" in initialData || true)) && (
            <div className="space-y-2">
              <Label htmlFor="comments">{clientType === "client-feedback" ? "Comments" : "Description"}</Label>
              <Textarea id="comments" {...form.register("comments" as never)} />
            </div>
          )}
        </CardContent>
      </Card>

      <div className="flex gap-3 justify-end">
        {onCancel && (
          <Button type="button" variant="outline" onClick={onCancel}>
            Cancel
          </Button>
        )}
        <Button type="submit" disabled={isLoading}>
          {isLoading ? "Saving..." : "Save"}
        </Button>
      </div>
    </form>
  );
}

